mapper.select:
SELECT ll.*, gl.guan_lang_name AS guanLangName
FROM t_zgsq_lian_lu ll
LEFT JOIN t_zgsq_guan_lang gl ON ll.guan_lang_id = gl.guan_lang_id AND gl.deleted = 0
WHERE ll.deleted = 0

    AND ll.lian_lu_no LIKE CONCAT('%', #{lianLuNo}, '%')


    AND ll.lian_lu_name LIKE CONCAT('%', #{lianLuName}, '%')


    AND ll.lian_lu_status = #{lianLuStatus}


    AND ll.guan_lang_id = #{guanLangId}

ORDER BY ll.lian_lu_id DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM t_zgsq_lian_lu ll
WHERE ll.deleted = 0

    AND ll.lian_lu_no LIKE CONCAT('%', #{lianLuNo}, '%')


    AND ll.lian_lu_name LIKE CONCAT('%', #{lianLuName}, '%')


    AND ll.lian_lu_status = #{lianLuStatus}


    AND ll.guan_lang_id = #{guanLangId}
